content:
.card {
  --card-inset: 12px;
  border: 1px solid #e6e8e1;
  border-radius: 14px;
  transition: border-color 180ms ease, box-shadow 180ms ease;
}
.card:hover { border-color: #cdd7c9; box-shadow: 0 8px 24px #243c2d0a; }
.media { background: #fff; border-bottom: 1px solid #f0f1ed; }
.productImage { padding: 8px; object-position: center; }
.info { padding: 14px 12px 12px; }
.title {
  min-height: 2.9em;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.45;
  letter-spacing: -.015em;
  color: #303a31;
}
.prices { padding: 12px 0; }
.price { color: #203d2b; font-size: 18px; line-height: 1.2; font-weight: 600; letter-spacing: -.035em; }
.salePrice { color: #dc2626; }
.badges { max-width: calc(100% - 64px); pointer-events: none; }
.badges > span {
  max-width: 100%;
  padding: 5px 7px;
  border-radius: 4px;
  background: #fffffff0;
  color: #344637;
  border: 1px solid #e7ebe2;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: .07em;
  line-height: 1;
  overflow-wrap: anywhere;
  box-shadow: none;
}
.badges > .discount { background: #edf2e7; color: #35512f; border-color: #e0e8d7; }
.action {
  display: flex;
  min-height: 48px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 4px calc(-1 * var(--card-inset)) calc(-1 * var(--card-inset));
  padding: 12px var(--card-inset);
  border-top: 1px solid #e6e8e1;
  background: #fff;
  color: #203d2b;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  transition: background-color 180ms ease;
}
.card:hover .action,
.action:focus-visible {
  background: #f6f8f3;
}
.actionArrow { transition: transform 180ms ease; }
.card:hover .actionArrow,
.action:focus-visible .actionArrow { transform: translateX(3px); }
.actionUnavailable { color: #737373; }
.card:hover .actionUnavailable,
.actionUnavailable:focus-visible { background: #fafafa; }
@media (min-width: 640px) {
  .card { --card-inset: 16px; }
  .productImage { padding: 12px; }
  .info { padding: 16px; }
  .title { font-size: 14px; }
  .price { font-size: 20px; }
  .badges > span { font-size: 9px; }
}
@media (prefers-reduced-motion: reduce) {
  .card, .action, .actionArrow { transition: none; }
  .card:hover .actionArrow, .action:focus-visible .actionArrow { transform: none; }
}
